public class StringPracticeAlgorithmsDemo {
    // 1. Two-Pointer In-Place Palindrome Check (O(N) time, O(1) space)
    public static boolean isPalindrome(String s) {
        int left = 0;
        int right = s.length() - 1;
        while (left < right) {
            if (s.charAt(left) != s.charAt(right)) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }

    // 2. Anagram Check via Frequency Array (O(N) time, O(1) space)
    public static boolean isAnagram(String s1, String s2) {
        if (s1.length() != s2.length()) return false;
        int[] freq = new int[26];
        for (int i = 0; i < s1.length(); i++) {
            freq[s1.charAt(i) - 'a']++;
            freq[s2.charAt(i) - 'a']--;
        }
        for (int count : freq) {
            if (count != 0) return false;
        }
        return true;
    }

    public static void main(String[] args) {
        System.out.println("radar is palindrome: " + isPalindrome("radar")); // true
        System.out.println("apple is palindrome: " + isPalindrome("apple")); // false

        System.out.println("silent & listen anagram: " + isAnagram("silent", "listen")); // true
        System.out.println("hello & world anagram: " + isAnagram("hello", "world"));   // false
    }
}

